const { Transform } = require('stream');

// Let's build a machine that converts all text to UPPERCASE
const uppercaseMachine = new Transform({
  transform(chunk, encoding, callback) {
    // 1. Receive the raw chunk
    const rawText = chunk.toString();

    // 2. Transform the data
    const upperText = rawText.toUpperCase();

    // 3. Push the transformed data out the readable side
    this.push(upperText);

    // 4. Signal we are done with this chunk
    callback();
  }
});

// We listen to the readable side of the machine
uppercaseMachine.on('data', (chunk) => {
  console.log("Output:", chunk.toString());
});

// We write to the machine
uppercaseMachine.write("hello ");
uppercaseMachine.write("world!");
uppercaseMachine.end();
